import { defineConfig } from "vitest/config";
export default defineConfig({
  test: {
    environment: "node",
    include: ["tests/**/*.test.ts"],
    // Rebuild better-sqlite3 before tests — prevents binary drift after nvm switches.
    globalSetup: ["./tests/setup/rebuild-sqlite.ts"],
    // Serialize test files to eliminate SQLite write contention.
    // pool:"forks" + maxWorkers:1 replaces the removed poolOptions.forks.singleFork (Vitest 4).
    pool: "forks",
    maxWorkers: 1,
    // Cold fork load of better-sqlite3 native module can exceed 5s default.
    testTimeout: 15000,
  },
});

/**
 * Newsletter Commerce MCP — Eval Runner
 *
 * Usage:
 *   npx tsx tests/eval-runner.ts               # fixture mode (mocked extractor)
 *   EVAL_LIVE=true npx tsx tests/eval-runner.ts # live mode (real OpenAI API)
 *
 * Fixture mode: injects a deterministic mock that returns all expectedProducts.
 * Live mode: calls extractProducts() with real OpenAI key from env.
 */

import type { NewsletterEvalCase, EvalResult } from "./eval-types.js";
import { ALL_SCORERS } from "./eval-scorers.js";
import { ALL_CASES } from "./eval-cases/index.js";
import type { ExtractionResult } from "../src/types.js";

// ---------------------------------------------------------------------------
// Fixture mock — returns expectedProducts as ProductMentions
// ---------------------------------------------------------------------------

function mockExtraction(evalCase: NewsletterEvalCase): ExtractionResult {
  return {
    newsletter_id: evalCase.id,
    products: evalCase.expectedProducts.map((ep) => ({
      name: ep.name,
      category: ep.category as import("../src/types.js").ProductCategory,
      confidence: 0.9,
      mention_context: "Mock extraction for fixture mode",
      recommendation_strength: "mentioned" as const,
      affiliate_link: null,
      is_sponsored: false,
    })),
    sponsor_sections: [],
    _meta: {
      processing_time_ms: 0,
      ai_cost_usd: 0,
      cache_hit: false,
    },
  };
}

// ---------------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------------

async function runCase(
  evalCase: NewsletterEvalCase,
  mode: "fixture" | "live"
): Promise<EvalResult> {
  const start = Date.now();
  let result: ExtractionResult;

  if (mode === "live") {
    const { extractProducts, setOpenAIClient } = await import("../src/extractor.js");
    const OpenAI = (await import("openai")).default;
    const apiKey = process.env.OPENAI_API_KEY;
    if (!apiKey) throw new Error("OPENAI_API_KEY not set for live eval");
    setOpenAIClient(new OpenAI({ apiKey }));
    const extracted = await extractProducts({ content: evalCase.content, newsletterId: evalCase.id });
    result = {
      newsletter_id: extracted.newsletter_id,
      products: extracted.products,
      sponsor_sections: extracted.sponsor_sections,
      _meta: { processing_time_ms: Date.now() - start, ai_cost_usd: extracted.ai_cost_usd, cache_hit: false },
    };
  } else {
    result = mockExtraction(evalCase);
  }

  const scores = ALL_SCORERS.map((scorer) => scorer(evalCase, result));
  const overallScore = Math.round(scores.reduce((s, r) => s + r.score, 0) / scores.length);

  return {
    caseId: evalCase.id,
    caseName: evalCase.name,
    timestamp: new Date().toISOString(),
    scores,
    overallScore,
    passed: scores.every((s) => s.passed),
    productsExtracted: result.products ?? [],
  };
}

async function main() {
  const mode = process.env.EVAL_LIVE === "true" ? "live" : "fixture";
  console.log(`\n🧪 Newsletter Commerce MCP — Eval (mode: ${mode})\n`);

  const results: EvalResult[] = [];
  for (const evalCase of ALL_CASES) {
    process.stdout.write(`  ${evalCase.name}... `);
    try {
      const result = await runCase(evalCase, mode);
      results.push(result);
      const status = result.passed ? "✅ PASS" : "❌ FAIL";
      console.log(`${status} (${result.overallScore}/100)`);
      for (const score of result.scores) {
        const icon = score.passed ? "  ✓" : "  ✗";
        console.log(`${icon} ${score.dimension}: ${score.score}/${score.target} — ${score.details}`);
      }
    } catch (err) {
      console.log(`💥 ERROR: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  const passed = results.filter((r) => r.passed).length;
  const total = results.length;
  console.log(`\nResults: ${passed}/${total} cases passed\n`);

  if (passed < total) process.exit(1);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

/**
 * Unit tests for edition-formatter.ts
 *
 * Pure formatting logic — no mocks or OpenAI calls needed.
 */

import { describe, it, expect } from "vitest";
import { generateEditionSection } from "../src/edition-formatter.js";
import type { ProductMention } from "../src/types.js";

const makeProduct = (overrides: Partial<ProductMention>): ProductMention => ({
  name: "Test Product",
  category: "saas",
  mention_context: "The author has used this for six months",
  confidence: 0.9,
  recommendation_strength: "strong",
  affiliate_link: null,
  is_sponsored: false,
  ...overrides,
});

const SAMPLE: ProductMention[] = [
  makeProduct({ name: "Notion AI", recommendation_strength: "strong", affiliate_link: "https://notion.so/ref" }),
  makeProduct({ name: "Beehiiv", recommendation_strength: "endorsed", confidence: 0.85, is_sponsored: true }),
  makeProduct({ name: "Linear", recommendation_strength: "mentioned", confidence: 0.7 }),
  makeProduct({ name: "Organic Pick", recommendation_strength: "organic", confidence: 0.85 }),
  makeProduct({ name: "Low Confidence", recommendation_strength: "strong", confidence: 0.3 }),
];

describe("generateEditionSection — markdown minimal", () => {
  it("renders affiliate link when present", () => {
    const result = generateEditionSection(SAMPLE, "markdown", "minimal");
    expect(result).toContain("[Notion AI](https://notion.so/ref)");
    expect(result).toContain("## Products in This Edition");
  });

  it("renders products without links as bold name", () => {
    const result = generateEditionSection(SAMPLE, "markdown", "minimal");
    expect(result).toContain("**Beehiiv**");
  });

  it("excludes low confidence products (< 0.6)", () => {
    const result = generateEditionSection(SAMPLE, "markdown", "minimal");
    expect(result).not.toContain("Low Confidence");
  });

  it("excludes organic products below 0.8 confidence", () => {
    const lowOrganics = [makeProduct({ name: "Weak Organic", recommendation_strength: "organic", confidence: 0.6 })];
    const result = generateEditionSection(lowOrganics, "markdown", "minimal");
    expect(result).toContain("No product mentions found");
  });
});

describe("generateEditionSection — markdown full", () => {
  it("groups by endorsement strength with headers", () => {
    const result = generateEditionSection(SAMPLE, "markdown", "full");
    expect(result).toContain("### ⭐ Top Picks");
    expect(result).toContain("### 👍 Endorsed");
  });

  it("includes mention context quote", () => {
    const result = generateEditionSection(SAMPLE, "markdown", "full");
    expect(result).toContain("used this for six months");
  });

  it("includes newsletter CTA", () => {
    const result = generateEditionSection(SAMPLE, "markdown", "full");
    expect(result).toContain("help keep this newsletter free");
  });

  it("merges organic into mentioned group", () => {
    const result = generateEditionSection(SAMPLE, "markdown", "full");
    expect(result).toContain("### 📍 Also Featured");
  });
});

describe("generateEditionSection — html", () => {
  it("returns html for minimal format", () => {
    const result = generateEditionSection(SAMPLE, "html", "minimal");
    expect(result).toContain("<h2>Products in This Edition</h2>");
    expect(result).toContain("<ul>");
    expect(result).toContain('<a href="https://notion.so/ref">Notion AI</a>');
  });

  it("returns html for full format", () => {
    const result = generateEditionSection(SAMPLE, "html", "full");
    expect(result).toContain("<h2>Products in This Edition</h2>");
    expect(result).toContain("<h3>⭐ Top Picks</h3>");
  });
});

describe("generateEditionSection — edge cases", () => {
  it("handles empty array gracefully", () => {
    const result = generateEditionSection([], "markdown", "full");
    expect(result).toContain("No product mentions found in this edition");
  });

  it("sorts strong before endorsed", () => {
    const result = generateEditionSection(SAMPLE, "markdown", "minimal");
    const notionIdx = result.indexOf("Notion AI");
    const beehiivIdx = result.indexOf("Beehiiv");
    expect(notionIdx).toBeLessThan(beehiivIdx);
  });
});

/**
 * Newsletter Commerce MCP — Eval Framework Types
 *
 * Quality evaluation for extraction accuracy on real-world newsletter content.
 * Three modes:
 *   fixture  — mocked extractor, tests scoring logic and schema correctness
 *   live     — real OpenAI calls, validates extraction quality on real content
 *   snapshot — update golden snapshots from live output
 */

import type { ProductMention } from "../src/types.js";

// ============================================================================
// EVAL CASE
// ============================================================================

export interface ExpectedProduct {
  /** Exact or partial product name match (case-insensitive) */
  name: string;
  /** Expected category */
  category: string;
  /** Must be present in output — failure if missing */
  required: boolean;
}

export interface NewsletterEvalCase {
  id: string;
  name: string;
  /** Data provenance — where the newsletter content was sourced from */
  source: string;
  /** Full newsletter content (real content from source) */
  content: string;
  /** Products we expect extraction to identify */
  expectedProducts: ExpectedProduct[];
  /** Max token budget for JSON output (default: 2000) */
  maxTokens?: number;
}

// ============================================================================
// EVAL RESULT
// ============================================================================

export interface ScorerResult {
  dimension: string;
  score: number;   // 0-100
  target: number;  // pass threshold
  details: string;
  passed: boolean;
}

export interface EvalResult {
  caseId: string;
  caseName: string;
  timestamp: string;
  scores: ScorerResult[];
  overallScore: number;
  passed: boolean;
  productsExtracted: ProductMention[];
}

/**
 * Input size limit tests (FIND-4).
 *
 * Verifies that the Zod schemas in server.ts enforce the expected upper bounds
 * on all user-supplied fields that reach OpenAI. Each test imports the exported
 * limit constants so the assertions stay in sync with the implementation.
 */

import { describe, it, expect } from "vitest";
import { z } from "zod";
import {
  CONTENT_MAX_CHARS,
  ID_MAX_CHARS,
  API_KEY_MAX_CHARS,
  CATEGORY_FILTER_ITEM_MAX,
  CATEGORY_FILTER_ARRAY_MAX,
  NEWSLETTER_IDS_ARRAY_MAX,
} from "../src/server.js";

// ============================================================================
// content (extract_newsletter_products, analyze_newsletter_sponsors)
// ============================================================================

describe("content field limits", () => {
  const schema = z.string().min(1).max(CONTENT_MAX_CHARS);

  it("accepts content at the exact max length", () => {
    expect(schema.safeParse("x".repeat(CONTENT_MAX_CHARS)).success).toBe(true);
  });

  it("rejects content one character over the limit", () => {
    const result = schema.safeParse("x".repeat(CONTENT_MAX_CHARS + 1));
    expect(result.success).toBe(false);
  });

  it("rejects empty content", () => {
    expect(schema.safeParse("").success).toBe(false);
  });
});

// ============================================================================
// newsletter_id field
// ============================================================================

describe("newsletter_id field limits", () => {
  const schema = z.string().max(ID_MAX_CHARS).optional();

  it("accepts an ID at the exact max length", () => {
    expect(schema.safeParse("a".repeat(ID_MAX_CHARS)).success).toBe(true);
  });

  it("rejects an ID one character over the limit", () => {
    const result = schema.safeParse("a".repeat(ID_MAX_CHARS + 1));
    expect(result.success).toBe(false);
  });

  it("accepts undefined (optional)", () => {
    expect(schema.safeParse(undefined).success).toBe(true);
  });
});

// ============================================================================
// api_key field
// ============================================================================

describe("api_key field limits", () => {
  const schema = z.string().max(API_KEY_MAX_CHARS).optional();

  it("accepts an api_key at the exact max length", () => {
    expect(schema.safeParse("k".repeat(API_KEY_MAX_CHARS)).success).toBe(true);
  });

  it("rejects an api_key one character over the limit", () => {
    const result = schema.safeParse("k".repeat(API_KEY_MAX_CHARS + 1));
    expect(result.success).toBe(false);
  });
});

// ============================================================================
// category_filter array
// ============================================================================

describe("category_filter array limits", () => {
  const schema = z
    .array(z.string().max(CATEGORY_FILTER_ITEM_MAX))
    .max(CATEGORY_FILTER_ARRAY_MAX)
    .optional();

  it("accepts an array at the max item count", () => {
    const input = Array.from({ length: CATEGORY_FILTER_ARRAY_MAX }, (_, i) => `cat${i}`);
    expect(schema.safeParse(input).success).toBe(true);
  });

  it("rejects an array one item over the max count", () => {
    const input = Array.from({ length: CATEGORY_FILTER_ARRAY_MAX + 1 }, (_, i) => `cat${i}`);
    expect(schema.safeParse(input).success).toBe(false);
  });

  it("rejects a category string over the item max length", () => {
    const input = ["c".repeat(CATEGORY_FILTER_ITEM_MAX + 1)];
    expect(schema.safeParse(input).success).toBe(false);
  });

  it("accepts undefined (optional)", () => {
    expect(schema.safeParse(undefined).success).toBe(true);
  });
});

// ============================================================================
// newsletter_ids array (track_product_trends)
// ============================================================================

describe("newsletter_ids array limits", () => {
  const schema = z
    .array(z.string().max(ID_MAX_CHARS))
    .min(1)
    .max(NEWSLETTER_IDS_ARRAY_MAX);

  it("accepts an array at the max count", () => {
    const input = Array.from({ length: NEWSLETTER_IDS_ARRAY_MAX }, (_, i) => `issue-${i}`);
    expect(schema.safeParse(input).success).toBe(true);
  });

  it("rejects an array one item over the max count", () => {
    const input = Array.from({ length: NEWSLETTER_IDS_ARRAY_MAX + 1 }, (_, i) => `issue-${i}`);
    expect(schema.safeParse(input).success).toBe(false);
  });

  it("rejects a newsletter ID over the ID max length", () => {
    const input = ["x".repeat(ID_MAX_CHARS + 1)];
    expect(schema.safeParse(input).success).toBe(false);
  });

  it("rejects an empty array (min 1)", () => {
    expect(schema.safeParse([]).success).toBe(false);
  });
});

/**
 * Server integration tests for newsletter-commerce-mcp.
 *
 * Verifies tool registrations, server structure, free tier enforcement,
 * and input validation. Does not start a real transport or call real OpenAI.
 */

import { describe, it, expect, beforeEach } from "vitest";

// ============================================================================
// SERVER CREATION
// ============================================================================

describe("createServer", () => {
  it("creates an MCP server without throwing", async () => {
    const { createServer } = await import("../src/server.js");
    expect(() => createServer()).not.toThrow();
  });

  it("returns a server with connect and tool methods", async () => {
    const { createServer } = await import("../src/server.js");
    const server = createServer();
    expect(server).toBeDefined();
    expect(typeof server.connect).toBe("function");
    expect(typeof server.tool).toBe("function");
  });
});

// ============================================================================
// TOOL REGISTRATION SMOKE TESTS
// ============================================================================

describe("tool registrations", () => {
  it("all 3 tools are registered (duplicate registration throws)", async () => {
    const { createServer } = await import("../src/server.js");
    const server = createServer();
    expect(server).toBeDefined();
  });

  it("extract_newsletter_products tool is registered", async () => {
    const { createServer } = await import("../src/server.js");
    const server = createServer();

    expect(() => {
      server.tool(
        "extract_newsletter_products",
        "duplicate",
        {},
        async () => ({ content: [] })
      );
    }).toThrow();
  });

  it("analyze_newsletter_sponsors tool is registered", async () => {
    const { createServer } = await import("../src/server.js");
    const server = createServer();

    expect(() => {
      server.tool(
        "analyze_newsletter_sponsors",
        "duplicate",
        {},
        async () => ({ content: [] })
      );
    }).toThrow();
