describe("extractProducts — graceful fallback", () => {
  beforeEach(() => {
    // Reset injected client between tests
    setOpenAIClient(null as unknown as import("openai").default);
  });

  it("returns empty arrays and error when OpenAI client throws", async () => {
    const mockClient = {
      chat: {
        completions: {
          create: vi.fn().mockRejectedValue(new Error("Network error")),
        },
      },
    };
    setOpenAIClient(mockClient as unknown as import("openai").default);

    const result = await extractProducts({
      content: "Some newsletter content",
      newsletterId: "test-nl",
    });

    expect(result.products).toEqual([]);
    expect(result.sponsor_sections).toEqual([]);
    expect(result.ai_cost_usd).toBe(0);
    expect(result.error).toContain("Network error");
  });

  it("does not retry on timeout error — fails fast to avoid doubling worst-case latency", async () => {
    // Timeouts are not retried: if LLM API is slow enough to hit 15s threshold,
    // a retry will also timeout, doubling latency (~20s → ~46s) with no gain.
    const create = vi.fn()
      .mockRejectedValueOnce(new Error("Request timed out"));
    setOpenAIClient({ chat: { completions: { create } } } as unknown as import("openai").default);

    const result = await extractProducts({
      content: "Some newsletter content",
      newsletterId: "test-nl-timeout",
    });

    expect(create).toHaveBeenCalledTimes(1);
    expect(result.error).toContain("timed out");
    expect(result.products).toEqual([]);
  });

  it("does not retry on non-retryable errors (generic network error)", async () => {
    const create = vi.fn().mockRejectedValue(new Error("Network error"));
    setOpenAIClient({ chat: { completions: { create } } } as unknown as import("openai").default);

    await extractProducts({ content: "test", newsletterId: "test-nl-no-retry" });

    // Non-retryable error: only 1 attempt, no retry
    expect(create).toHaveBeenCalledTimes(1);
  });

  it("returns normalized products when OpenAI returns valid JSON", async () => {
    const mockResponse = {
      choices: [
        {
          message: {
            content: JSON.stringify({
              products: [
                {
                  name: "Acme Tool",
                  category: "saas",
                  mention_context: "I love Acme Tool for productivity",
                  recommendation_strength: "endorsed",
                  affiliate_link: null,
                  confidence: 0.85,
                  is_sponsored: false,
                },
              ],
              sponsor_sections: [],
            }),
          },
        },
      ],
      usage: { prompt_tokens: 100, completion_tokens: 50 },
    };

    const mockClient = {
      chat: {
        completions: {
          create: vi.fn().mockResolvedValue(mockResponse),
        },
      },
    };
    setOpenAIClient(mockClient as unknown as import("openai").default);

    const result = await extractProducts({
      content: "I love Acme Tool for productivity",
      newsletterId: "test-nl",
    });

    expect(result.products).toHaveLength(1);
    expect(result.products[0]?.name).toBe("Acme Tool");
    expect(result.products[0]?.category).toBe("saas");
    expect(result.ai_cost_usd).toBeGreaterThan(0);
    expect(result.error).toBeUndefined();
  });

  it("handles HTML content by stripping tags before extraction", async () => {
    const mockClient = {
      chat: {
        completions: {
          create: vi.fn().mockResolvedValue({
            choices: [{ message: { content: '{"products":[],"sponsor_sections":[]}' } }],
            usage: { prompt_tokens: 50, completion_tokens: 10 },
          }),
        },
      },
    };
    setOpenAIClient(mockClient as unknown as import("openai").default);

    await extractProducts({
      content: "<p>Hello <b>world</b></p>",
      newsletterId: "html-test",
    });

    // Check that the user message sent to OpenAI did not contain HTML tags
    const callArgs = (mockClient.chat.completions.create as ReturnType<typeof vi.fn>).mock.calls[0]?.[0];
    const userMessage = callArgs?.messages?.[1]?.content as string;
    expect(userMessage).not.toMatch(/<[a-zA-Z]/);
    expect(userMessage).toContain("Hello");
    expect(userMessage).toContain("world");
  });

  it("applies category filter to returned products", async () => {
    const mockResponse = {
      choices: [
        {
          message: {
            content: JSON.stringify({
              products: [
                {
                  name: "SaaS Tool",
                  category: "saas",
                  mention_context: "ctx",
                  recommendation_strength: "mentioned",
                  affiliate_link: null,
                  confidence: 0.8,
                  is_sponsored: false,
                },
                {
                  name: "Physical Good",
                  category: "physical_goods",
                  mention_context: "ctx",
                  recommendation_strength: "mentioned",
                  affiliate_link: null,
                  confidence: 0.7,
                  is_sponsored: false,
                },
              ],
              sponsor_sections: [],
            }),
          },
        },
      ],
      usage: { prompt_tokens: 100, completion_tokens: 50 },
    };

    const mockClient = {
      chat: {
        completions: {
          create: vi.fn().mockResolvedValue(mockResponse),
        },
      },
    };
    setOpenAIClient(mockClient as unknown as import("openai").default);

    const result = await extractProducts({
      content: "Newsletter content",
      newsletterId: "filter-test",
      categoryFilter: ["saas"],
    });

    expect(result.products).toHaveLength(1);
    expect(result.products[0]?.name).toBe("SaaS Tool");
  });

  it("returns timeout error when extraction exceeds 25s budget", async () => {
    // Mock OpenAI to hang indefinitely (simulates slow response on high-load days)
    const mockClient = {
      chat: {
        completions: {
          create: vi.fn().mockImplementation(
            () => new Promise((_resolve) => setTimeout(_resolve, 30_000)),
          ),
        },
      },
    };
    setOpenAIClient(mockClient as unknown as import("openai").default);

    const result = await extractProducts({
      content: "Some newsletter content",
      newsletterId: "test-timeout",
    });

    expect(result.products).toHaveLength(0);
    expect(result.sponsor_sections).toHaveLength(0);
    expect(result.ai_cost_usd).toBe(0);
    expect(result.error).toMatch(/extraction_timeout/);
  }, 30_000); // vitest timeout > 25s for this test
});

